<?php

declare(strict_types=1);

namespace App\Http;

use Sahil\Contracts\Foundation\ApplicationContract;
use Sahil\Contracts\View\ViewContract;
use Sahil\Http\Request;
use Sahil\Http\Response;

/**
 * Renders the authentication pages generated by `php sahil make:auth`.
 *
 * These handlers render pages only: they do not authenticate users, create
 * accounts or send reset mail. When you add real accounts, keep the templates
 * and replace the method bodies with calls to the framework's auth and
 * password-reset services, then register POST routes for the same paths in
 * `routes/auth.php`.
 */
final class AuthController
{
    public function __construct(
        private readonly ViewContract $views,
        private readonly ApplicationContract $application,
    ) {
    }

    public function showLogin(): Response
    {
        return $this->page('auth.login');
    }

    public function showRegister(): Response
    {
        return $this->page('auth.register');
    }

    public function showForgotPassword(): Response
    {
        return $this->page('auth.forgot-password');
    }

    /**
     * @param array<string, string> $params route parameters; `token` comes from
     *                                      the reset link in the mail
     */
    public function showResetPassword(Request $request, array $params = []): Response
    {
        return $this->page('auth.reset-password', [
            'token' => (string) ($params['token'] ?? ''),
        ]);
    }

    public function showDashboard(): Response
    {
